INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (89, 167, 'BOPP crystal adhesive tape jumbo rolls', '../upload/image/20180922/20180922163734_31676.jpg', '<p></p><p>BOPP crystal adhesive tape jumbo rolls</p> <p>BOPP crystal adhesive packing tape jumbo-rolls ( Bopp Transparent &amp; Brown Tapes acrylic water base size &amp; solvent &amp; rubber ) is widely used for slitting into medium/smaller rolls and for heavy-duty cartons sealing .1) BOPP super clear adhesive packaging tape with water based acrylic adhesive, high-tensile strength and adhesion <br/> BOPP adhesive tape also called Packing Sealing Adhesive Tapes,packing tape,adhesive tape,BOPP tape jumbo rolls,BOPP tan tape, BOPP brown tape,Polypropylene tape,BOPP clear tape, BOPP printed tape,BOPP brown tape,BOPP smaller rolls, BOPP water based tape, BOPP solvent based tape,BOPP rubber based tape,BOPP acrylic tape,BOPP crystal tape,BOPP jumbo rolls<br/> 2) Colors: Transparent/clear,tan,yellowish,red,dark brown,light tan,white,red,blue,green,black,multicolor and printed logo/letter so on. <br/> 3) Thickness: 35,36,38,39,40,41,42,45,48,50,53,55,58,60,63,65,68mic<br/> 4) Width: 520mm,980mm,1020mm,1270mm,1280mm,1300mm,1600mm,1620mm,1640mm and others <br/> 5) Length: 3000m,4000m,4500m,6000m<br/> 6.) Size:jumbo rolls tape <br/> 6) Qty: 1200rolls/day<br/> Customer own requirement is available for us. Such as : buyer''s own printed OEM logos,private label,particular size and private package styles.</p>', '2026-09-06 20:58:45');
